import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

export interface Resource {
  id: string;
  type: string;
  name: string;
  tags: Record<string, string>;
  stack_id: string | null;
  depends_on: string[];
  cost_month_cents: number;
  created_at: string;
}

