// relies on (unknown provider fields are dropped).
export function toResource(raw: Record<string, unknown>): Resource {
  return {
    id: raw.id as string,
    type: raw.type as string,
    name: raw.name as string,
    tags: (raw.tags as Record<string, string> | undefined) ?? {},
