    cost_month_cents: (raw.cost_month_cents as number | undefined) ?? 0,
    created_at: raw.created_at as string,
  };
}

export class ApiError extends Error {
  status: number;
  body: unknown;
  constructor(status: number, body: unknown, message: string) {
    super(message);
    this.status = status;
    this.body = body;
