import assert from "node:assert/strict";
import { test } from "node:test";
import { toResource } from "../src/api.ts";
import { branchOf, byBranch, isUntagged, matches, toEnvctlResource } from "../src/filter.ts";
import { buildPlan } from "../src/plan.ts";

function raw(id: string, fields: Record<string, unknown> = {}): Record<string, unknown> {
  return { id, type: "instance", name: id, ...fields };
}

test("envctl preserves case-insensitive label keys before shared normalization", () => {
  const input = raw("cdk", { labels: { bRaNcH: "Feat-A", TEAM: "payments" } });
  const r = toEnvctlResource(input);
  assert.equal(branchOf(r), "Feat-A");
  assert.ok(matches(r, [["team", "payments"]]));
  assert.equal(isUntagged(r), false);
  assert.equal(byBranch([r]).get("Feat-A")?.length, 1);
  assert.equal(buildPlan([r], "feat-a").steps.length, 0); // values are exact
  assert.equal(buildPlan([r], "Feat-A").steps.length, 1);
  assert.deepEqual(toResource(input).tags, {}); // shared contract unchanged
  assert.equal(input.tags, undefined); // no input mutation
});

test("normalization preserves tags, defaults, and explicit tag precedence", () => {
  const r = toEnvctlResource(raw("mixed", {
    labels: { Branch: "feat-a", Team: "payments" },
    tags: { branch: "feat-b", owner: "ops" },
  }));
  assert.deepEqual(r.tags, { branch: "feat-b", team: "payments", owner: "ops" });
  assert.deepEqual(toEnvctlResource(raw("empty", { tags: null, labels: null })).tags, {});
  assert.deepEqual(r.depends_on, []);
  assert.equal(r.stack_id, null);
});

test("plans include label-only dependents and volumes, but not similar branch names", () => {
  const resources = [
    raw("net", { tags: { branch: "feat-a" }, stack_id: "stk-feat-a" }),
    raw("boot", { stack_id: "stk-feat-a" }),
    raw("cdk-volume", { labels: { BRANCH: "feat-a" } }),
    raw("cdk-instance", { labels: { Branch: "feat-a" }, depends_on: ["net", "boot", "cdk-volume"] }),
    raw("other", { labels: { Branch: "feat-a-v2" } }),
    raw("other-stack", { stack_id: "stk-feat-a-v2" }),
    raw("conflicting-tag", { tags: { branch: "feat-b" }, stack_id: "stk-feat-a" }),
    raw("orphan"),
  ].map(toEnvctlResource);
  const plan = buildPlan(resources, "feat-a");
  assert.deepEqual(plan.blocked, []);
  assert.deepEqual(plan.steps.map((s) => s.id).sort(), ["boot", "cdk-instance", "cdk-volume", "net"]);
  assert.equal(plan.steps[0].id, "cdk-instance");
});

test("genuine external label-only dependents still block teardown", () => {
  const resources = [
    raw("net", { tags: { branch: "feat-a" } }),
    raw("external", { labels: { Branch: "feat-b" }, depends_on: ["net"] }),
  ].map(toEnvctlResource);
  assert.deepEqual(buildPlan(resources, "feat-a").blocked, [{ id: "net", dependents: ["external"] }]);
});
