import { loadConfig } from './src/api.ts';
const before=JSON.parse(readFileSync('/tmp/envctl-before.json','utf8'));
const plan=JSON.parse(readFileSync('/tmp/envctl-ledger-plan.json','utf8'));
const branch=r=>r.tags?.branch ?? Object.entries(r.labels ?? {}).find(([k])=>k.toLowerCase()==='branch')?.[1];
const expected=new Set(before.filter(r=>branch(r)==='feat-ledger'||(branch(r)===undefined&&r.stack_id==='stk-feat-ledger')).map(r=>r.id));
const ids=plan.steps.map(s=>s.id);
assert.equal(ids.length,29);
assert.deepEqual(new Set(ids),expected);
assert.deepEqual(plan.blocked,[]);
const pos=new Map(ids.map((id,i)=>[id,i]));
for(const r of before) for(const d of r.depends_on ?? []) if(expected.has(d)) {
  assert.ok(expected.has(r.id),`external dependency: ${r.id} -> ${d}`);
  assert.ok(pos.get(r.id)<pos.get(d),`bad deletion order: ${r.id} -> ${d}`);
}
console.log('Saved plan verified: exactly 29 branch-owned resources; valid dependent-first order.');
const cfg=loadConfig(); const after=[];
let cursor='0';
while(cursor!==null){
  const response=await fetch(cfg.baseUrl+`/v1/resources?cursor=${encodeURIComponent(cursor)}&limit=20`,{headers:{authorization:`Bearer ${cfg.token}`}});
  if(response.status===429){
    const wait=Number(response.headers.get('retry-after')??5);
    await response.text();
    console.log(`Rate limited; waiting ${wait}s`);
    await new Promise(resolve=>setTimeout(resolve,wait*1000));
    continue;
  }
  assert.ok(response.ok,`inventory HTTP ${response.status}`);
  const page=await response.json();after.push(...page.resources);cursor=page.next_cursor;
}
writeFileSync('/tmp/envctl-after.json',JSON.stringify(after,null,2));
assert.equal(after.length,37);
assert.deepEqual(after,before.filter(r=>!expected.has(r.id)));
assert.equal(after.filter(r=>branch(r)==='feat-ledger'||r.stack_id==='stk-feat-ledger').length,0);
console.log('Verified: all 29 feat-ledger resources are gone; all 37 unrelated resources are unchanged.');
